package com.hbm.blocks.machine.rbmk;
import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.*; import net.minecraft.core.BlockPos; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState;
public class RBMKModerator extends RBMKBase { public final double moderation; public RBMKModerator(Properties properties) { this(properties, 1D); } public RBMKModerator(Properties properties, double moderation) { super(properties); this.moderation = moderation; } @Override protected BlockEntityType<? extends BlockEntityRBMKBase> beType() { return ModRBMKBlockEntities.RBMK_MODERATOR.get(); } @Override protected BlockEntityRBMKBase createCore(BlockPos pos, BlockState state) { return new BlockEntityRBMKModerator(pos, state); } }
